class FenwickTree:
    def __init__(self, size):
        self.size = size
        self.tree = [0] * (size + 1)

    def update(self, idx, delta):
        idx += 1  # 1-based
        while idx <= self.size:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        idx += 1  # 1-based
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

    def range_query(self, left, right):
        return self.query(right) - self.query(left - 1)

def minimumDeletions(s: str, queries: list[list[int]]) -> list[int]:
    n = len(s)
    if n == 0:
        return []

    s = list(s)  # mutable
    bad = [0] * (n - 1)
    ft = FenwickTree(n - 1)

    # Build initial bad array and FT
    for i in range(n - 1):
        bad[i] = 1 if s[i] == s[i + 1] else 0
        ft.update(i, bad[i])

    ans = []
    for q in queries:
        tp = q[0]
        if tp == 1:
            # Flip
            j = q[1]
            s[j] = 'b' if s[j] == 'a' else 'a'

            # Update bad[j-1] if exists
            if j > 0:
                old_bad = bad[j - 1]
                new_bad = 1 if s[j - 1] == s[j] else 0
                delta = new_bad - old_bad
                bad[j - 1] = new_bad
                ft.update(j - 1, delta)

            # Update bad[j] if exists
            if j < n - 1:
                old_bad = bad[j]
                new_bad = 1 if s[j] == s[j + 1] else 0
                delta = new_bad - old_bad
                bad[j] = new_bad
                ft.update(j, delta)

        else:
            # Type 2: query sum bad[l..r-1]
            l, r = q[1], q[2]
            if l >= r:
                ans.append(0)
            else:
                ans.append(ft.range_query(l, r - 1))

    return ans
